        v.visit_table(pos)?
            .visit_union::<Geometry, _>(
                "geom_type",
                Self::VT_GEOM_TYPE,
                "geom",
                Self::VT_GEOM,
                true,
                |key, v, pos| match key {
                    Geometry::Point => v
                        .verify_union_variant::<flatbuffers::ForwardsUOffset<Point>>(
                            "Geometry::Point",
                            pos,
                        ),
                    Geometry::Line => v.verify_union_variant::<flatbuffers::ForwardsUOffset<Line>>(
                        "Geometry::Line",
                        pos,
                    ),
                    Geometry::MultiLine => v
                        .verify_union_variant::<flatbuffers::ForwardsUOffset<MultiLine>>(
                            "Geometry::MultiLine",
                            pos,
                        ),
                    Geometry::Polygon => v
                        .verify_union_variant::<flatbuffers::ForwardsUOffset<Polygon>>(
                            "Geometry::Polygon",
                            pos,
                        ),
                    Geometry::MultiPolygon => v
                        .verify_union_variant::<flatbuffers::ForwardsUOffset<MultiPolygon>>(
                            "Geometry::MultiPolygon",
                            pos,
                        ),
                    _ => Ok(()),
                },
            )?
            .finish();
        Ok(())
